# ============================================================
# Data (post-1945, as in book chapter)
# ============================================================
pms <- tribble(
  ~name,           ~party,        ~start,       ~end,         ~exit,
  "Attlee",        "Labour",      "1945-07-26", "1951-10-26", "electoral",
  "Churchill",     "Conservative","1951-10-26", "1955-04-05", "voluntary",
  "Eden",          "Conservative","1955-04-06", "1957-01-09", "voluntary",
  "Macmillan",     "Conservative","1957-01-10", "1963-10-18", "voluntary",
  "Douglas-Home",  "Conservative","1963-10-19", "1964-10-16", "electoral",
  "Wilson I",      "Labour",      "1964-10-16", "1970-06-19", "electoral",
  "Heath",         "Conservative","1970-06-19", "1974-03-04", "electoral",
  "Wilson II",     "Labour",      "1974-03-04", "1976-04-05", "voluntary",
  "Callaghan",     "Labour",      "1976-04-05", "1979-05-04", "electoral",
  "Thatcher",      "Conservative","1979-05-04", "1990-11-28", "internal",
  "Major",         "Conservative","1990-11-28", "1997-05-02", "electoral",
  "Blair",         "Labour",      "1997-05-02", "2007-06-27", "voluntary",
  "Brown",         "Labour",      "2007-06-27", "2010-05-11", "electoral",
  "Cameron",       "Conservative","2010-05-11", "2016-07-13", "no_choice",
  "May",           "Conservative","2016-07-13", "2019-07-24", "no_choice",
  "Johnson",       "Conservative","2019-07-24", "2022-09-06", "internal",
  "Truss",         "Conservative","2022-09-06", "2022-10-25", "internal",
  "Sunak",         "Conservative","2022-10-25", "2024-07-05", "electoral",
  "Starmer",       "Labour",      "2024-07-05", "2026-07-20", "internal"
  # Handover to Burnham verified as Mon 20 Jul 2026 (King's appointment; was 07-16).
  # Burnham (incumbent, ongoing) is deliberately NOT added here: Figs 2.1-2.3 analyse
  # COMPLETED PM tenures + departure types, so an ongoing PM with censored (~days)
  # tenure and no departure would corrupt the tenure bars and the break analysis.
  # Burnham is carried in the canonical PM data (data/processed/pm_tenure.csv) as an
  # 'ongoing' row with NA tenure, matching how script 02 excludes 'ongoing' officers.
) |>
  mutate(
    start        = as.Date(start),
    end          = as.Date(end),
    tenure_days  = as.numeric(end - start),
    tenure_years = tenure_days / 365.25,
    forced       = as.integer(exit %in% c("internal", "no_choice")),
    seq_num      = row_number()
  )

n <- nrow(pms)
y <- pms$tenure_years
t_seq <- pms$seq_num

cat("N =", n, "PMs\n\n")

# ============================================================
# Grayscale palette
# ============================================================
dark  <- "#000000"
mid   <- "#4d4d4d"
light <- "#888888"

# ============================================================
# REGRESSION-BASED CHOW TEST
#
# At each candidate break k, fit:
#   y = a1 + b1*t  for PMs 1..k
#   y = a2 + b2*t  for PMs (k+1)..n
# Compare pooled RSS with split RSS.
# F = ((RSS_pool - RSS1 - RSS2) / p) / ((RSS1 + RSS2) / (n - 2p))
# where p = 2 (intercept + slope)
# ============================================================

# --- fast closed-form simple-OLS residual sum of squares (intercept + one slope) ---
# Numerically identical to lm(y ~ t) RSS (verified to < 1e-13) but ~100x faster.
# This removes the permutation-loop bottleneck: the old version called lm() hundreds
# of thousands of times (10,000 perms x every candidate break x 3 fits), which pushed
# the script past the 200s road-test cap. set.seed(42) and n_perm are unchanged, so
# the reported permutation p-values are identical.
.rss_lin <- function(y, t) {
  n <- length(y)
  if (n < 3) return(0)                 # <=2 points fit exactly (RSS 0), matching lm
  mt <- mean(t); my <- mean(y)
  Stt <- sum((t - mt)^2)
  if (Stt == 0) return(sum((y - my)^2))
  b <- sum((t - mt) * (y - my)) / Stt
  sum((y - (my - b * mt) - b * t)^2)
}
chow_regression <- function(y, t, k) {
  n <- length(y)
  if (k < 3 || k > n - 3) return(NA_real_)
  rss_pool  <- .rss_lin(y, t)
  rss_split <- .rss_lin(y[1:k], t[1:k]) + .rss_lin(y[(k+1):n], t[(k+1):n])
  p <- 2
  ((rss_pool - rss_split) / p) / (rss_split / (n - 2 * p))
}

# ============================================================
# A. TENURE: Regression-based Chow at each candidate break
# ============================================================

cat("========== TENURE: REGRESSION-BASED CHOW ==========\n\n")

ks <- seq(3, n - 3)
fstats_tenure <- sapply(ks, function(k) chow_regression(y, t_seq, k))

fs_tenure <- tibble(
  k     = ks,
  name  = pms$name[ks],
  year  = as.integer(format(pms$start[ks], "%Y")),
  fstat = fstats_tenure
) |> filter(!is.na(fstat))

crit_reg <- qf(0.95, df1 = 2, df2 = n - 4)
bp_tenure <- fs_tenure |> slice_max(fstat, n = 1)

cat(sprintf("Data-preferred break: %s (%d)\n", bp_tenure$name, bp_tenure$year))
cat(sprintf("F(2,%d) = %.2f, critical value (5%%) = %.2f\n", n - 4, bp_tenure$fstat, crit_reg))
cat(sprintf("Significant: %s\n", ifelse(bp_tenure$fstat > crit_reg, "YES", "NO")))

cat("\nAll F-statistics:\n")
for (i in 1:nrow(fs_tenure)) {
  sig <- ifelse(fs_tenure$fstat[i] > crit_reg, " *", "")
  cat(sprintf("  %-15s (%d): F = %5.2f%s\n",
              fs_tenure$name[i], fs_tenure$year[i], fs_tenure$fstat[i], sig))
}

# Permutation test
set.seed(42)
n_perm <- 10000
obs_maxF_tenure <- bp_tenure$fstat
perm_maxF_tenure <- replicate(n_perm, {
  y_p <- sample(y)
  f_p <- sapply(ks, function(k) chow_regression(y_p, t_seq, k))
  max(f_p, na.rm = TRUE)
})
perm_p_tenure <- mean(perm_maxF_tenure >= obs_maxF_tenure)
cat(sprintf("\nPermutation p = %.4f (%d permutations)\n", perm_p_tenure, n_perm))

# Slope before and after the break
bp_k <- bp_tenure$k
m_before <- lm(y[1:bp_k] ~ t_seq[1:bp_k])
m_after  <- lm(y[(bp_k+1):n] ~ t_seq[(bp_k+1):n])
cat(sprintf("\nSlope before %s: %.3f years per PM (tenure %s)\n",
            bp_tenure$name, coef(m_before)[2],
            ifelse(coef(m_before)[2] > 0, "lengthening", "shortening")))
cat(sprintf("Slope after  %s: %.3f years per PM (tenure %s)\n",
            bp_tenure$name, coef(m_after)[2],
            ifelse(coef(m_after)[2] > 0, "lengthening", "shortening")))

# ============================================================
# B. BAI-PERRON MULTIPLE BREAKPOINTS (TENURE)
# ============================================================

cat("\n\n========== BAI-PERRON: MULTIPLE BREAKPOINTS (TENURE) ==========\n")

# strucchange breakpoints() function
# h = minimum segment size (fraction). With N=18, h=0.2 gives min 3-4 obs per segment
bp_result <- tryCatch({
  breakpoints(y ~ t_seq, h = 0.2, breaks = 3)
}, error = function(e) {
  cat("Bai-Perron failed:", e$message, "\n")
  NULL
})

if (!is.null(bp_result)) {
  cat("BIC for 0-3 breaks:\n")
  bp_summary <- summary(bp_result)
  print(bp_summary)

  # Optimal number of breaks by BIC
  bic_vals <- c(
    BIC(lm(y ~ t_seq)),  # 0 breaks
    sapply(1:min(3, length(bp_result$breakpoints)), function(m) {
      tryCatch({
        bp_m <- breakpoints(y ~ t_seq, h = 0.2, breaks = m)
        if (length(bp_m$breakpoints) == m && !any(is.na(bp_m$breakpoints))) {
          AIC(bp_m, k = log(n))  # BIC
        } else NA
      }, error = function(e) NA)
    })
  )
  names(bic_vals) <- paste0(0:min(3, length(bp_result$breakpoints)), " breaks")
  cat("\nBIC values:\n")
  print(round(bic_vals, 2))

  optimal_breaks <- which.min(bic_vals) - 1
  cat(sprintf("\nBIC-optimal: %d break(s)\n", optimal_breaks))

  if (optimal_breaks > 0) {
    bp_opt <- breakpoints(y ~ t_seq, h = 0.2, breaks = optimal_breaks)
    cat("Break location(s):\n")
    for (b in bp_opt$breakpoints) {
      cat(sprintf("  PM %d: %s (%d)\n", b, pms$name[b],
                  as.integer(format(pms$start[b], "%Y"))))
    }
  }

  # SupF test for existence of at least one break
  sup_f <- sctest(y ~ t_seq, type = "supF", h = 0.2)
  cat(sprintf("\nSup-F test: F = %.2f, p = %.4f\n", sup_f$statistic, sup_f$p.value))
}

# ============================================================
# C. DEPARTURES: Regression-based Chow
# ============================================================

cat("\n\n========== DEPARTURES: REGRESSION-BASED CHOW ==========\n\n")

y_dep <- pms$forced
ks_dep <- seq(2, n - 2)
fstats_dep <- sapply(ks_dep, function(k) chow_regression(y_dep, t_seq, k))

fs_dep <- tibble(
  k     = ks_dep,
  name  = pms$name[ks_dep],
  year  = as.integer(format(pms$start[ks_dep], "%Y")),
  fstat = fstats_dep
) |> filter(!is.na(fstat))

bp_dep <- fs_dep |> slice_max(fstat, n = 1)
crit_dep <- qf(0.95, df1 = 2, df2 = n - 4)

cat(sprintf("Data-preferred break: %s (%d)\n", bp_dep$name, bp_dep$year))
cat(sprintf("F(2,%d) = %.2f, critical value (5%%) = %.2f\n", n - 4, bp_dep$fstat, crit_dep))
cat(sprintf("Significant: %s\n", ifelse(bp_dep$fstat > crit_dep, "YES", "NO")))

cat("\nAll F-statistics:\n")
for (i in 1:nrow(fs_dep)) {
  sig <- ifelse(fs_dep$fstat[i] > crit_dep, " *", "")
  cat(sprintf("  %-15s (%d): F = %5.2f%s\n",
              fs_dep$name[i], fs_dep$year[i], fs_dep$fstat[i], sig))
}

# Permutation test for departures
obs_maxF_dep <- bp_dep$fstat
perm_maxF_dep <- replicate(n_perm, {
  y_p <- sample(y_dep)
  f_p <- sapply(ks_dep, function(k) chow_regression(y_p, t_seq, k))
  max(f_p, na.rm = TRUE)
})
perm_p_dep <- mean(perm_maxF_dep >= obs_maxF_dep)
cat(sprintf("\nPermutation p = %.4f\n", perm_p_dep))

# Fisher exact at data-preferred break
bp_dep_k <- bp_dep$k
fisher_tab <- pms |>
  mutate(period = if_else(row_number() <= bp_dep_k, "Before", "After")) |>
  count(period, exit_grp = if_else(forced == 1, "forced", "normal")) |>
  pivot_wider(names_from = exit_grp, values_from = n, values_fill = 0)
fisher_result <- fisher.test(as.matrix(fisher_tab[, -1]))
cat(sprintf("Fisher exact at %s: p = %.4f\n", bp_dep$name, fisher_result$p.value))

# ============================================================
# D. THE INTERACTION: tenure × forced departures
#
# Key question: does forced departure CAUSE shorter tenure
# for the next PM, or does shorter tenure make forced
# departure more likely? Or both (feedback loop)?
#
# Three tests:
#   1. Does inheriting from a forced predecessor shorten tenure?
#   2. Does the tenure-departure relationship change over time?
#   3. Combined model: tenure = f(sequence, prev_forced, era)
# ============================================================

cat("\n\n========== INTERACTION: TENURE × FORCED DEPARTURES ==========\n")

pms_lag <- pms |>
  mutate(
    prev_forced = lag(forced),
    prev_tenure = lag(tenure_years),
    prev_name   = lag(name),
    post_callaghan = as.numeric(seq_num > which(pms$name == "Callaghan")),
    post_cameron   = as.numeric(seq_num >= which(pms$name == "Cameron"))
  )

d <- pms_lag |> filter(!is.na(prev_forced))

# --- Test 1: Does inheriting from forced predecessor shorten tenure? ---
cat("\n--- Test 1: Inherited instability ---\n")
cat("tenure_i = a + b*(previous PM forced)\n\n")

m1 <- lm(tenure_years ~ prev_forced, data = d)
cat(sprintf("Intercept: %.2f years (after normal departure)\n", coef(m1)[1]))
cat(sprintf("prev_forced: %.2f years (effect of inheriting from forced)\n", coef(m1)[2]))
cat(sprintf("p = %.3f\n", summary(m1)$coefficients[2, 4]))

# --- Test 2: Does the tenure-departure link change over time? ---
cat("\n--- Test 2: Era interaction ---\n")
cat("tenure_i = a + b*prev_forced + c*post_cameron + d*prev_forced*post_cameron\n\n")

m2 <- lm(tenure_years ~ prev_forced * post_cameron, data = d)
cat("Coefficients:\n")
print(round(summary(m2)$coefficients, 3))

# --- Test 3: Combined model ---
cat("\n--- Test 3: Combined model ---\n")
cat("tenure_i = a + b*seq + c*prev_forced + d*prev_tenure\n\n")

m3 <- lm(tenure_years ~ seq_num + prev_forced + prev_tenure, data = d)
cat("Coefficients:\n")
print(round(summary(m3)$coefficients, 3))

# --- Test 4: Does short tenure predict forced departure (reverse causation)? ---
cat("\n--- Test 4: Reverse causation (short tenure → forced departure) ---\n")
cat("forced_i = logit(a + b*tenure_i)\n\n")

m4 <- glm(forced ~ tenure_years, data = pms, family = binomial)
cat("Coefficients:\n")
print(round(summary(m4)$coefficients, 3))
cat(sprintf("\nShort tenure predicts forced departure: coef = %.3f (p = %.3f)\n",
            coef(m4)[2], summary(m4)$coefficients[2, 4]))
cat("Direction: negative coefficient = shorter tenure → more likely forced out\n")

# --- Test 5: Feedback loop (does forced departure breed forced departure?) ---
cat("\n--- Test 5: Feedback loop (forced breeds forced) ---\n")
cat("forced_i = logit(a + b*prev_forced)\n\n")

d_fb <- pms_lag |> filter(!is.na(prev_forced))
m5 <- glm(forced ~ prev_forced, data = d_fb, family = binomial)
cat("Coefficients:\n")
print(round(summary(m5)$coefficients, 3))

# Transition matrix
cat("\nTransition matrix (row = previous departure, col = current):\n")
trans <- table(Previous = d_fb$prev_forced, Current = d_fb$forced)
rownames(trans) <- c("Prev normal", "Prev forced")
colnames(trans) <- c("Current normal", "Current forced")
print(trans)

# ============================================================
# E. FIGURES
# ============================================================

# Figure 2.1 revised: tenure bars + regression-based Chow
p1_bars <- ggplot(pms, aes(x = reorder(name, start), y = tenure_years)) +
  geom_col(width = 0.7, fill = mid) +
  geom_hline(yintercept = mean(y), linetype = "dashed", colour = light, linewidth = 0.4) +
  annotate("text", x = 2, y = mean(y) + 0.3,
           label = paste0("Mean = ", round(mean(y), 1), " yrs"),
           colour = light, size = 2.5, hjust = 0) +
  scale_y_continuous(expand = expansion(mult = c(0, 0.05))) +
  labs(x = NULL, y = "Years in office") +
  theme_minimal(base_size = 10) +
  theme(axis.text.x = element_text(angle = 60, hjust = 1, size = 7),
        panel.grid.minor = element_blank())

p1_chow <- ggplot(fs_tenure, aes(x = year, y = fstat)) +
  geom_hline(yintercept = crit_reg, linetype = "dashed", colour = light, linewidth = 0.5) +
  geom_line(colour = dark, linewidth = 0.6) +
  geom_point(colour = dark, size = 1.8) +
  geom_point(data = bp_tenure, shape = 21, fill = "white",
             colour = dark, size = 3.5, stroke = 1.3) +
  annotate("text", x = bp_tenure$year - 1, y = bp_tenure$fstat,
           label = paste0(bp_tenure$name, " (", bp_tenure$year, ")"),
           colour = dark, size = 3, hjust = 1, fontface = "bold") +
  annotate("text", x = min(fs_tenure$year), y = crit_reg + 0.3,
           label = "5% critical value", colour = light, size = 2.5, hjust = 0) +
  scale_x_continuous(breaks = fs_tenure$year) +
  labs(x = NULL, y = "Chow F(2, N\u22124)") +
  theme_minimal(base_size = 10) +
  theme(axis.text.x = element_text(angle = 45, hjust = 1, size = 6),
        panel.grid.minor = element_blank())

# ============================================================================
# ⭐ FIGURE 2.1 = TWO PANELS ON A SHARED PRIME-MINISTER AXIS.
# PJ, 17 Aug: "hard to read the PM - thinking of putting into figure 2.1 as panel B?", then
# "new figure 2.1 is not good - we want the cumulated figure underneath the pms - try again."
#
# ⛔ FIRST ATTEMPT REJECTED: a strip of filled/hollow markers. It showed the pattern but threw away
# the cumulative series that was the whole point of the old Figure 2.2.
# ⭐ THIS VERSION: panel B is the CUMULATIVE proportion of premierships ending in a forced
# departure — the old 2.2 measure, cumsum(forced)/seq_num — drawn beneath the tenure bars.
#
# ⭐ BOTH PANELS USE THE NUMERIC PM SEQUENCE as x, not the name factor. That is what guarantees the
# two panels line up: bar n sits directly above cumulative point n. The names are written ONCE,
# under panel B, which was PJ's original complaint about the standalone Figure 2.2 — it plotted
# against year_end, so the Prime Ministers were never labelled at all.
# ============================================================================
pms <- pms[order(pms$start), ]
pms$seq_num <- seq_len(nrow(pms))
pms$cum_prop <- cumsum(pms$forced) / pms$seq_num

XPM <- scale_x_continuous(breaks = pms$seq_num, labels = pms$name,
                          expand = expansion(add = 0.7))

p1_bars <- ggplot(pms, aes(x = seq_num, y = tenure_years)) +
  geom_col(width = 0.7, fill = mid) +
  geom_hline(yintercept = mean(pms$tenure_years), linetype = "dashed",
             colour = light, linewidth = 0.4) +
  annotate("text", x = 1.2, y = mean(pms$tenure_years) + 0.35,
           label = paste0("Mean = ", round(mean(pms$tenure_years), 1), " yrs"),
           colour = light, size = 2.5, hjust = 0) +
  XPM +
  scale_y_continuous(expand = expansion(mult = c(0, 0.05))) +
  labs(tag = "A", subtitle = "Length of each premiership", x = NULL, y = "Years in office") +
  theme_minimal(base_size = 10) +
  theme(legend.position = "none",
        panel.grid.minor = element_blank(), panel.grid.major.x = element_blank(),
        axis.text.x = element_blank(),
        plot.subtitle = element_text(face = "italic", colour = "grey30", size = 9,
                                     margin = margin(b = 10)),
        plot.tag = element_text(face = "bold", size = 11),
        plot.margin = margin(t = 4, r = 6, b = 16, l = 6))

p1_cum <- ggplot(pms, aes(x = seq_num, y = cum_prop)) +
  geom_step(colour = dark, linewidth = 0.7) +
  geom_point(aes(shape = ifelse(forced == 1, "f", "n")), size = 2.3,
             colour = dark, fill = "white", stroke = 0.8) +
  # ⚠ PJ, 17 Aug: "needs the key in the figure, at the bottom." FIGURE_STYLE_GUIDE.md prefers direct
  # labels over legends, but that rule is written for multi-series line charts where a legend forces
  # the eye off the data. A two-shape key read once at the foot of the figure does not, and PJ asked
  # for it explicitly. Deviation recorded rather than silent.
  scale_shape_manual(values = c(f = 16, n = 21),
                     labels = c(f = "Forced departure", n = "Left by election or by choice"),
                     name = NULL) +
  XPM +
  scale_y_continuous(labels = scales::percent_format(accuracy = 1),
                     limits = c(0, 0.52), expand = c(0, 0)) +
  labs(tag = "B", subtitle = "Cumulative share of premierships ending in a forced departure",
       x = NULL, y = "Cumulative share") +
  theme_minimal(base_size = 10) +
  theme(legend.position = "bottom",
        legend.margin = margin(t = 2),
        legend.text = element_text(size = 8, colour = "grey20"),
        legend.key.spacing.x = unit(14, "pt"),
        panel.grid.minor = element_blank(), panel.grid.major.x = element_blank(),
        axis.text.x = element_text(angle = 60, hjust = 1, size = 7),
        plot.subtitle = element_text(face = "italic", colour = "grey30", size = 9,
                                     margin = margin(b = 10)),
        plot.tag = element_text(face = "bold", size = 11),
        plot.margin = margin(t = 10, r = 6, b = 4, l = 6))

fig_2_1 <- (p1_bars / p1_cum) +
  plot_layout(heights = c(2.0, 1.6)) +
  plot_annotation(
    title = "Figure 2.1: Prime Ministerial tenure and departure, 1945–2026",
# 17 Aug, PJ: "some of the titles are too small typface". Title size was a raw pt value while
# canvases run 6.5-10 in, so the SAME pt looked large on a narrow figure and small on a wide
# one - a 68% spread in apparent size. Titles are now set at ~1.75 pt per inch of canvas
# (this figure is 7.4 in wide, so 13 pt), which is the ratio the narrow figures already had.
    theme = theme(plot.title = element_text(face = "bold", size = 13, margin = margin(b = 8)))
  )

ggsave("figures/fig_2_1_pm_tenure.png", fig_2_1, width = 7.4, height = 6.6, dpi = 300)

# Figure 2.2 revised: departures + regression-based Chow
exit_shapes <- c("internal" = 16, "no_choice" = 17, "electoral" = 1, "voluntary" = 2)
exit_greys  <- c("internal" = "#000000", "no_choice" = "#4d4d4d",
                 "electoral" = "#000000", "voluntary" = "#4d4d4d")

deps_plot <- pms |>
  mutate(cum_prop = cumsum(forced) / seq_num,
         year_end = as.integer(format(end, "%Y")))

p2_top <- ggplot(deps_plot, aes(x = year_end, y = cum_prop)) +
  geom_step(colour = dark, linewidth = 0.8) +
  geom_point(aes(shape = exit, colour = exit), size = 3) +
  scale_shape_manual(values = exit_shapes,
                     labels = c("internal" = "Internal removal", "no_choice" = "No-choice resignation",
                                "electoral" = "Electoral defeat", "voluntary" = "Voluntary"),
                     name = "Departure type") +
  scale_colour_manual(values = exit_greys,
                      labels = c("internal" = "Internal removal", "no_choice" = "No-choice resignation",
                                 "electoral" = "Electoral defeat", "voluntary" = "Voluntary"),
                      name = "Departure type") +
  scale_y_continuous(labels = percent_format(), limits = c(0, 0.5)) +
  labs(x = NULL, y = "Cumulative proportion\nforced departures") +
  theme_minimal(base_size = 10) +
  theme(axis.text.x = element_text(angle = 45, hjust = 1, size = 8),
        panel.grid.minor = element_blank(),
        legend.position = "bottom", legend.text = element_text(size = 7.5))

p2_bot <- ggplot(fs_dep, aes(x = year, y = fstat)) +
  geom_hline(yintercept = crit_dep, linetype = "dashed", colour = light, linewidth = 0.5) +
  geom_line(colour = dark, linewidth = 0.6) +
  geom_point(colour = dark, size = 1.8) +
  geom_point(data = bp_dep, shape = 21, fill = "white",
             colour = dark, size = 3.5, stroke = 1.3) +
  annotate("text", x = bp_dep$year + 0.5, y = bp_dep$fstat + 0.5,
           label = paste0(bp_dep$name, " (", bp_dep$year, ")"),
           colour = dark, size = 3, hjust = 0, fontface = "bold") +
  scale_x_continuous(breaks = fs_dep$year) +
  labs(x = NULL, y = "Chow F(2, N\u22124)") +
  theme_minimal(base_size = 10) +
  theme(axis.text.x = element_text(angle = 45, hjust = 1, size = 6),
        panel.grid.minor = element_blank())

fig_2_2 <- p2_top +
  plot_annotation(
    title = "Figure 2.2: PM departures by type, 1951\u20132024",
    theme = theme(plot.title = element_text(face = "bold", size = 13))
  )

