# Figure 2.3: Tenure × departure interaction
p3 <- ggplot(pms, aes(x = seq_num, y = tenure_years)) +
  geom_point(aes(shape = factor(forced)), size = 3, colour = dark) +
  geom_smooth(method = "lm", se = TRUE, colour = mid, linetype = "dashed", linewidth = 0.5) +
  scale_shape_manual(values = c("0" = 1, "1" = 16),
                     labels = c("Normal departure", "Forced departure"),
                     name = NULL) +
  scale_x_continuous(breaks = pms$seq_num, labels = pms$name) +
  labs(x = NULL, y = "Tenure (years)",
       title = "Figure 2.3: Tenure and departure type",
       subtitle = "Filled = forced departure. Linear trend shows declining tenure trajectory.",
       caption = "Forced departures cluster at the end of the series (Cameron onwards).") +
  theme_minimal(base_size = 10) +
  theme(axis.text.x = element_text(angle = 60, hjust = 1, size = 7),
        legend.position = "bottom",
        plot.title = element_text(face = "bold", size = 13),
        plot.subtitle = element_text(size = 9, colour = "grey30"),
        plot.caption = element_text(size = 7.5, colour = "grey40"))

